// Chat Completions has no search session: the client sends the full
// conversation as `messages` on every request. This looks up prior turns
// already stored for this n8n chat session and appends the new user message.
//
// Static data is per-workflow, in-memory-backed storage that n8n persists to
// the database after each execution. It's fine for demos/small deployments,
// but it resets if you clear it manually, and it isn't shared across workers
// in a scaled/queue-mode setup. For production, replace this lookup/store
// pair with a real data store (a Data Table node, a database, Redis, etc.)
// keyed the same way.
const staticData = $getWorkflowStaticData('global');
staticData.conversations = staticData.conversations || {};

const n8nSessionId = $json.sessionId;
const history = staticData.conversations[n8nSessionId] || [];
const messages = [...history, { role: 'user', content: $json.chatInput }];

return [
  {
    json: {
      ...$json,
      messages,
    },
  },
];

// Appends the assistant reply to the messages just sent, so the next
// message in this n8n chat session includes the full conversation.
const staticData = $getWorkflowStaticData('global');
staticData.conversations = staticData.conversations || {};

const triggerData = $('When chat message received').item.json;
const sent = $('Look Up Conversation').item.json.messages;
staticData.conversations[triggerData.sessionId] = [
  ...sent,
  { role: 'assistant', content: $json.content },
];

return [
  {
    json: {
      ...triggerData,
      content: $json.content,
    },
  },
];
